```python
class TrieNode:
    __slots__ = ("children", "is_end")

    def __init__(self):
        self.children = {}
        self.is_end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """Insert a word into the trie."""
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word: str) -> bool:
        """Return True if the exact word exists in the trie."""
        node = self._find_node(word)
        return node is not None and node.is_end

    def starts_with(self, prefix: str) -> bool:
        """Return True if any word in the trie starts with the given prefix."""
        return self._find_node(prefix) is not None

    def autocomplete(self, prefix: str, limit: int = 3) -> list[str]:
        """Return up to `limit` completions for `prefix`, in lexical order."""
        node = self._find_node(prefix)
        if node is None:
            return []

        results: list[str] = []
        self._collect(node, prefix, results, limit)
        return results

    def _find_node(self, s: str) -> "TrieNode | None":
        node = self.root
        for ch in s:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

    def _collect(self, node: TrieNode, path: str, results: list, limit: int) -> None:
        if len(results) >= limit:
            return
        if node.is_end:
            results.append(path)
            if len(results) >= limit:
                return
        # Sort children keys for lexical order traversal
        for ch in sorted(node.children):
            self._collect(node.children[ch], path + ch, results, limit)
            if len(results) >= limit:
                return
