# Thread-Safe LRU Cache in C++

Here's a complete implementation with a custom doubly linked list and mutex-based synchronization:

```cpp
#include <unordered_map>
#include <mutex>
#include <shared_mutex>
#include <optional>
#include <cstddef>

template <typename Key, typename Value>
class LRUCache {
private:
    struct Node {
        Key key;
        Value value;
        Node* prev;
        Node* next;

        Node(const Key& k, const Value& v)
            : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    // Sentinel-based doubly linked list.
    // head->next is the most-recently-used (MRU)
    // tail->prev is the least-recently-used (LRU)
    Node* head_;
    Node* tail_;

    std::unordered_map<Key, Node*> map_;
    std::size_t capacity_;

    // mutable so const methods (if any) can lock it
    mutable std::mutex mtx_;

    // --- list helpers (must be called under lock) ---

    void detach(Node* node) noexcept {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        node->prev = nullptr;
        node->next = nullptr;
    }

    void pushFront(Node* node) noexcept {
        node->next = head_->next;
        node->prev = head_;
        head_->next->prev = node;
        head_->next = node;
    }

    void moveToFront(Node* node) noexcept {
        detach(node);
        pushFront(node);
    }

    Node* popBack() noexcept {
        if (tail_->prev == head_) return nullptr; // empty
        Node* node = tail_->prev;
        detach(node);
        return node;
    }

public:
    explicit LRUCache(std::size_t capacity)
        : head_(new Node(Key{}, Value{})),
          tail_(new Node(Key{}, Value{})),
          capacity_(capacity) {
        if (capacity_ == 0) {
            // Avoid undefined semantics; keep a minimal valid state.
            // Callers should pass capacity > 0.
        }
        head_->next = tail_;
        tail_->prev = head_;
    }

    ~LRUCache() {
        // No need to lock in destructor; assumes no concurrent access at teardown.
        Node* cur = head_;
        while (cur) {
            Node* nxt = cur->next;
            delete cur;
            cur = nxt;
        }
    }

    // Non-copyable, non-movable for simplicity (mutex isn't movable anyway).
    LRUCache(const LRUCache&) = delete;
    LRUCache& operator=(const LRUCache&) = delete;
    LRUCache(LRUCache&&) = delete;
    LRUCache& operator=(LRUCache&&) = delete;

    /// Returns the value if present, std::nullopt otherwise.
    /// On hit, marks the key as most recently used.
    std::optional<Value> get(const Key& key) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = map_.find(key);
        if (it == map_.end()) return std::nullopt;

        moveToFront(it->second);
        return it->second->value;
    }

    /// Inserts or updates the value for `key`.
    /// Evicts the LRU entry if capacity is exceeded.
    void put(const Key& key, const Value& value) {
        std::lock_guard<std::mutex> lock(mtx_);
        if (capacity_ == 0) return;

        auto it = map_.find(key);
        if (it != map_.end()) {
            it->second->value = value;
            moveToFront(it->second);
            return;
        }

        if (map_.size() >= capacity_) {
            Node* evicted = popBack();
            if (evicted) {
                map_.erase(evicted->key);
                delete evicted;
            }
        }

        Node* node = new Node(key, value);
        pushFront(node);
        map_.emplace(key, node);
    }

    /// Removes a key. Returns true if the key existed.
    bool erase(const Key& key) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = map_.find(key);
        if (it == map_.end()) return false;
        Node* node = it->second;
        detach(node);
        map_.erase(it);
        delete node;
        return true;
    }

    std::size_t size() const {
        std::lock_guard<std::mutex> lock(mtx_);
        return map_.size();
    }

    std::size_t capacity() const noexcept {
        return capacity_;
    }
};
```

