```rust
use std::cell::RefCell;
use std::rc::Rc;

type TreeLink = Option<Rc<RefCell<TreeNode>>>;

#[derive(Debug)]
pub struct TreeNode {
    pub val: i32,
    pub left: TreeLink,
    pub right: TreeLink,
}

impl TreeNode {
    pub fn new(val: i32) -> Rc<RefCell<Self>> {
        Rc::new(RefCell::new(TreeNode {
            val,
            left: None,
            right: None,
        }))
    }
}

const NULL_SENTINEL: &str = "#";
const SEP: char = ',';

pub struct Codec;

impl Codec {
    pub fn new() -> Self {
        Codec
    }

    /// Serialize a tree to a comma-separated preorder string.
    /// Null children are encoded as `#`.
    pub fn serialize(&self, root: TreeLink) -> String {
        let mut out = String::new();
        Self::serialize_into(&root, &mut out);
        out
    }

    fn serialize_into(node: &TreeLink, out: &mut String) {
        match node {
            None => {
                if !out.is_empty() {
                    out.push(SEP);
                }
                out.push_str(NULL_SENTINEL);
            }
            Some(n) => {
                if !out.is_empty() {
                    out.push(SEP);
                }
                let n = n.borrow();
                out.push_str(&n.val.to_string());
                Self::serialize_into(&n.left, out);
                Self::serialize_into(&n.right, out);
            }
        }
    }

    /// Deserialize a string produced by `serialize` back into a tree.
    pub fn deserialize(&self, data: String) -> TreeLink {
        if data.is_empty() {
            return None;
        }
        let mut iter = data.split(SEP);
        Self::build(&mut iter)
    }

    fn build<'a, I: Iterator<Item = &'a str>>(iter: &mut I) -> TreeLink {
        match iter.next() {
            None => None,
            Some(tok) if tok == NULL_SENTINEL => None,
            Some(tok) => {
                let val: i32 = tok.parse().expect("invalid integer token");
                let node = TreeNode::new(val);
                node.borrow_mut().left = Self::build(iter);
                node.borrow_mut().right = Self::build(iter);
                Some(node)
            }
        }
    }
}

impl Default for Codec {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn build_sample() -> TreeLink {
        // Tree:
        //        1
        //       / \
        //      2   3
        //         / \
        //        4   5
        let root = TreeNode::new(1);
        let n2 = TreeNode::new(2);
        let n3 = TreeNode::new(3);
        let n4 = TreeNode::new(4);
        let n5 = TreeNode::new(5);
        n3.borrow_mut().left = Some(n4);
        n3.borrow_mut().right = Some(n5);
        root.borrow_mut().left = Some(n2);
        root.borrow_mut().right = Some(n3);
        Some(root)
    }

    #[test]
    fn roundtrip_sample() {
        let codec = Codec::new();
        let tree = build_sample();
        let s = codec.serialize(tree);
        assert_eq!(s, "1,2,#,#,3,4,#,#,5,#,#");
        let restored = codec.deserialize(s.clone());
        assert_eq!(codec.serialize(restored), s);
    }

    #[test]
    fn roundtrip_empty() {
        let codec = Codec::new();
        let s = codec.serialize(None);
        assert_eq!(s, "#");
        let restored = codec.deserialize(s);
        assert!(restored.is_none());
    }

