// rateLimiter.js
const WINDOW_MS = 1000;   // 1 second
const MAX_REQUESTS = 5;

const ipRequests = new Map(); // ip -> array of timestamps

function rateLimiter(req, res, next) {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const windowStart = now - WINDOW_MS;

  // Get or initialize timestamps for this IP
  let timestamps = ipRequests.get(ip) || [];

  // Sliding window: drop timestamps outside the window
  timestamps = timestamps.filter(ts => ts > windowStart);

  if (timestamps.length >= MAX_REQUESTS) {
    const retryAfter = Math.ceil((timestamps[0] + WINDOW_MS - now) / 1000);
    res.set('Retry-After', retryAfter);
    return res.status(429).json({
      error: 'Too Many Requests',
      message: `Limit of ${MAX_REQUESTS} requests per second exceeded.`,
      retryAfter,
    });
  }

  timestamps.push(now);
  ipRequests.set(ip, timestamps);

  // Helpful headers
  res.set('X-RateLimit-Limit', MAX_REQUESTS);
  res.set('X-RateLimit-Remaining', MAX_REQUESTS - timestamps.length);

  next();
}

// Periodic cleanup so the map doesn't grow forever
setInterval(() => {
  const cutoff = Date.now() - WINDOW_MS;
  for (const [ip, ts] of ipRequests) {
    const fresh = ts.filter(t => t > cutoff);
    if (fresh.length === 0) ipRequests.delete(ip);
    else ipRequests.set(ip, fresh);
  }
}, 5000).unref();

module.exports = rateLimiter;
